// The compiler continues after errors:
xiom build                  # Shows all errors
xiom check --max-errors 10  # Limit to 10 errors

// Recovery points (where parser resyncs):
// After: ;  }  )  ]  (on newlines in some contexts)

code_template:
// This code has multiple errors — can the parser recover?
fn main() -> Int {
  let x =      // Error 1: missing expression
  let y: Str = 42;  // Error 2: type mismatch
  return z;    // Error 3: undefined variable
}

// Fix all errors to compile

solution:
fn main() -> Int {
  let x = 42;
  let y: Str = "hello";
  return x;
}
